<?php
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_role(['Faculty']);
$user=current_user();$faculty=$pdo->prepare('SELECT * FROM faculty WHERE user_id=?');$faculty->execute([$user['id']]);$faculty=$faculty->fetch();
$search=trim($_GET['q']??'');$rows=[];
if($search!==''){ $st=$pdo->prepare('SELECT s.*,u.name,u.email,d.name department_name FROM students s JOIN users u ON u.id=s.user_id LEFT JOIN departments d ON d.id=s.department_id WHERE s.usn LIKE ? AND s.department_id=? ORDER BY u.name');$st->execute(['%'.$search.'%',$faculty['department_id']]);$rows=$st->fetchAll();}
$pageTitle='Assigned Students | CLEARX';require_once __DIR__.'/../includes/header.php';
?><div class="app-layout"><?php require_once __DIR__.'/../includes/sidebar.php';?><main class="app-main"><header class="topbar"><button class="menu-toggle"><i class="fa-solid fa-bars"></i></button><div class="topbar-user"><b><?=e($user['name'])?></b><span>Faculty</span></div><div class="avatar"><?=e(strtoupper(substr($user['name'],0,2)))?></div></header><div class="content"><div class="page-header"><div><p>ASSIGNED STUDENTS</p><h1>Student Directory</h1></div></div><section class="panel"><form method="get" style="display:flex;gap:8px;margin-bottom:12px"><input class="search-box" name="q" value="<?=e($search)?>" placeholder="Search by USN"><button class="action-btn" type="submit">Search</button></form><div class="table-wrap"><table class="data-table"><thead><tr><th>Name</th><th>USN</th><th>Department</th><th>Semester</th><th>Email</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['usn'])?></td><td><?=e($r['department_name'])?></td><td><?=e($r['semester'])?></td><td><?=e($r['email'])?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="5"><?= $search?'No matching student found.':'Enter a USN to search.' ?></td></tr><?php endif;?></tbody></table></div></section></div><?php require_once __DIR__.'/../includes/footer.php';?></main></div>
